package vn.edu.fpt.seal.modules.support.service; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import vn.edu.fpt.seal.common.exception.ApiException; import vn.edu.fpt.seal.modules.support.dto.*; import vn.edu.fpt.seal.modules.support.entity.SupportTicket; import vn.edu.fpt.seal.modules.support.repository.SupportTicketRepository; import vn.edu.fpt.seal.modules.user.repository.UserRepository; import java.util.*; @Service @RequiredArgsConstructor public class SupportTicketService{private final SupportTicketRepository repo; private final UserRepository userRepo; @Transactional(readOnly=true) public List<SupportTicketResponse> list(UUID requesterId){return (requesterId==null?repo.findTop100ByOrderByCreatedAtDesc():repo.findByRequesterIdOrderByCreatedAtDesc(requesterId)).stream().map(this::map).toList();} @Transactional public SupportTicketResponse create(CreateSupportTicketRequest r,UUID requesterId){var u=userRepo.findById(requesterId).orElseThrow(()->ApiException.notFound("Requester not found")); return map(repo.save(SupportTicket.builder().requester(u).category(r.category()).priority(r.priority()).subject(r.subject().trim()).description(r.description().trim()).build()));} private SupportTicketResponse map(SupportTicket t){var u=t.getRequester(); return new SupportTicketResponse(t.getId(),u.getId(),u.getFullName(),u.getEmail(),t.getCategory(),t.getPriority(),t.getSubject(),t.getDescription(),t.getStatus(),t.getCreatedAt(),t.getUpdatedAt());}}
